function openAccount(){if(cloudUser){go('Profile');return}setAuthMode('signin')}
function continueLocally(){try{localStorage.setItem(GUEST_STORAGE,'yes')}catch(e){}authScreen='app';authNotice='';render()}
function authView(){if(authScreen==='loading')return '<section class="auth-loading"><h1>Opening your journal</h1><p>Restoring your saved sign-in…</p><button class="text section-gap" onclick="continueLocally()">Continue on this device</button></section>';const signup=authMode==='signup',forgot=authMode==='forgot',update=authMode==='update',confirm=authMode==='confirm';const title=signup?'Create your account':forgot?'Reset your password':update?'Choose a new password':confirm?'Check your email':'Welcome back';return `<div class="auth-layout"><section class="hero auth-photo"><div><h2>Keep every round.</h2><p>Your scores, courses, and memories. Ready whenever you are.</p></div></section><section class="auth-form-panel"><h1>${title}</h1><p class="auth-description">${signup?'One account for your golf, on every device.':forgot?'We’ll email you a link to reset your password.':update?'Use at least 8 characters.':confirm?'Confirm your email address, then return here to log in.':'Log in to pick up where you left off.'}</p><p id="auth-status" class="auth-message" role="status">${esc(authNotice)}</p>${confirm?`<p>We sent a confirmation email to <strong>${esc(authEmail)}</strong>.</p><button class="auth-submit" onclick="setAuthMode('signin')">Back to log in</button><button class="text" onclick="resendConfirmation()">Resend confirmation email</button>`:`<form id="account-form" onsubmit="submitAccount(event)">${signup?'<label>Your name<input name="name" autocomplete="name" maxlength="50" required></label>':''}${!update?`<label>Email address<input name="email" type="email" autocomplete="email" value="${esc(authEmail)}" required></label>`:''}${!forgot?`<label>Password<div class="password-field"><input id="account-password" aria-label="Password" name="password" type="password" autocomplete="${signup||update?'new-password':'current-password'}" minlength="8" required><button type="button" onclick="toggleAccountPassword(this)" aria-label="Show password">Show</button></div></label>`:''}${signup||update?'<label>Confirm password<input name="confirm" type="password" autocomplete="new-password" minlength="8" required></label>':''}${!signup&&!forgot&&!update?'<div class="auth-secondary"><span class="auth-note" style="margin:0">You’ll stay logged in on this device.</span></div>':''}<button class="auth-submit" ${authWorking?'disabled':''}>${signup?'Create account':forgot?'Send reset link':update?'Save new password':'Log in'}</button></form>`}${!confirm?`<div class="auth-switch">${signup?'Already have an account?':forgot||update?'Remember your password?':'New to Dogleg?'} <button class="text" onclick="setAuthMode('${signup||forgot||update?'signin':'signup'}')">${signup||forgot||update?'Log in':'Create an account'}</button></div>`:''}<button class="text local-link" onclick="continueLocally()">Continue without an account</button><p class="auth-note">Your browser journal stays on this device. After logging in, you can import it into your account.</p></section></div>`}
function toggleAccountPassword(button){const input=document.querySelector('#account-password');input.type=input.type==='password'?'text':'password';button.textContent=input.type==='password'?'Show':'Hide';button.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password')}
async function acceptAuthSession(session,event){if(event==='TOKEN_REFRESHED'&&session?.user?.id===cloudUser?.id){cloudUser=session.user;return}if(session?.user){if(event==='PASSWORD_RECOVERY'){authMode='update';authScreen='signin';authNotice='';}else if(authMode!=='update'){authScreen='app'}try{localStorage.removeItem(GUEST_STORAGE)}catch(e){}await cloudAttach(session.user,event==='INITIAL_SESSION');render()}else{let guest=false;try{guest=localStorage.getItem(GUEST_STORAGE)==='yes'}catch(e){}authScreen=guest?'app':'signin';authMode='signin';await cloudAttach(null);render()}}
async function cloudBoot(){try{const session=JSON.parse(localStorage.getItem(AUTH_STORAGE)||'null'),cache=session?.user?.id&&JSON.parse(localStorage.getItem(KEY+':account:'+session.user.id)||'null');if(cache&&cloudValid(cache.data)){cloudUser=session.user;state=cache.data;cloudRevision=cache.revision;cloudDirty=cache.dirty;authScreen='app';cloudStatus='Saved on this device · Connecting to your account.'}else if(localStorage.getItem(GUEST_STORAGE)==='yes'){authScreen='app'}}catch(e){}render();try{await cloudInit()}catch(e){if(authScreen==='loading')authScreen='signin';authMessage('Unable to connect right now. Try again, or continue on this device.');if(cloudUser)cloudMessage('Offline · Changes are cached on this device.');render()}}
async function submitAccount(event){event.preventDefault();if(authWorking)return;const form=event.target,fields=new FormData(form),mode=authMode,email=String(fields.get('email')||authEmail).trim(),password=fields.get('password');if((mode==='signup'||mode==='update')&&password!==fields.get('confirm'))return authMessage('The passwords don’t match. Try again.');authWorking=true;form.querySelectorAll('button').forEach(b=>b.disabled=true);authMessage(mode==='forgot'?'Sending your reset link…':'Connecting…');try{const client=await cloudInit();authEmail=email;let result;if(mode==='signup'){result=await client.auth.signUp({email,password,options:{emailRedirectTo:'https://doglegclub.com/',data:{display_name:fields.get('name').trim()}}})}else if(mode==='forgot'){result=await client.auth.resetPasswordForEmail(email,{redirectTo:'https://doglegclub.com/'})}else if(mode==='update'){result=await client.auth.updateUser({password})}else{result=await client.auth.signInWithPassword({email,password})}if(result.error)throw result.error;form.reset();if(mode==='forgot'){authMessage('If an account exists for that email, a reset link is on its way.')}else if(mode==='update'){authMode='signin';authScreen='app';authNotice='';render();toast('Password updated. You’re logged in.')}else if(mode==='signup'&&!result.data.session){authMode='confirm';authNotice='';render()}else{authMode='signin';authScreen='app';await cloudAttach(result.data.user);go('Home')}}catch(error){authMessage(error.message||'Could not connect. Please try again.')}finally{authWorking=false;form.querySelectorAll('button').forEach(b=>b.disabled=false)}}
async function resendConfirmation(){if(authWorking)return;authWorking=true;try{const client=await cloudInit(),{error}=await client.auth.resend({type:'signup',email:authEmail,options:{emailRedirectTo:'https://doglegclub.com/'}});if(error)throw error;authMessage('Confirmation email requested. Check your inbox and spam folder.')}catch(e){authMessage(e.message||'Could not resend confirmation. Try again shortly.')}finally{authWorking=false}}
async function reconnectCloud(){try{const client=await cloudInit(),{data,error}=await client.auth.getSession();if(error)throw error;await acceptAuthSession(data.session,'INITIAL_SESSION');if(cloudUser&&cloudReady&&cloudDirty)cloudSave()}catch(e){cloudMessage('Connection unavailable. Your journal remains cached on this device.')}}
function cloudValid(data){return validBackup(data)&&data.profile&&typeof data.profile.name==='string'&&data.profile.name.length<=50&&typeof data.profile.home==='string'&&data.profile.home.length<=100&&Number.isInteger(data.profile.goal)&&data.profile.goal>=1&&data.profile.goal<=365}
function cloudMerge(current,incoming){const merged=JSON.parse(JSON.stringify(current));for(const k of ['rounds','notes','friends','challenges','shared']){const map=new Map(current[k].map(x=>[x.id,x]));for(const x of incoming[k])if(!map.has(x.id))map.set(x.id,x);merged[k]=[...map.values()]}merged.invites=[...new Set([...current.invites,...incoming.invites])];return merged}
function cloudCacheKey(){return KEY+':account:'+cloudUser.id}
function cloudCache(){try{localStorage.setItem(cloudCacheKey(),JSON.stringify({data:state,revision:cloudRevision,dirty:cloudDirty}));return true}catch(e){storageOK=false;toast('Device storage is full. Keep this page open and export a backup.');return false}}
function cloudMessage(message){cloudStatus=message;const el=document.querySelector('#cloud-status');if(el)el.textContent=message;const footer=document.querySelector('.footer span:last-child');if(footer&&cloudUser)footer.textContent='V7 · '+message}
function cloudPanel(){return `<section class="card section-gap"><h2>Your account</h2><p id="cloud-status" class="muted section-gap" role="status">${esc(cloudStatus)}</p>${cloudUser?`<div class="account-summary section-gap"><div class="grow"><strong>${esc(cloudUser.email)}</strong><p class="feature-caption">Logged in on this device. Your private journal saves automatically.</p></div><button class="secondary" onclick="cloudSignOut()">Log out</button></div><div class="friend-actions"><button onclick="cloudSave()">Save now</button><button class="secondary" onclick="cloudReloadPrompt()">Load latest cloud journal</button><button class="secondary" onclick="cloudImportGuest()">Import this browser’s original journal</button></div>`:`<p class="feature-caption">Create an account to keep your rounds across devices. You’ll stay logged in between rounds.</p><div class="friend-actions"><button onclick="setAuthMode('signin')">Log in</button><button class="secondary" onclick="setAuthMode('signup')">Create account</button></div>`}</section>`}
async function cloudInit(){if(cloudClient)return cloudClient;if(cloudLoading)return cloudLoading;cloudLoading=(async()=>{if(!window.supabase){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.118.0/dist/umd/supabase.js';s.onload=resolve;s.onerror=()=>{s.remove();reject(Error('Cloud connection unavailable. Your local journal is still available.'))};document.head.append(s)})}cloudClient=window.supabase.createClient(CLOUD_URL,CLOUD_KEY,{auth:{storageKey:AUTH_STORAGE,persistSession:true,autoRefreshToken:true,storage:localStorage,detectSessionInUrl:true}});cloudClient.auth.onAuthStateChange((event,session)=>{if(['INITIAL_SESSION','SIGNED_IN','SIGNED_OUT','TOKEN_REFRESHED','PASSWORD_RECOVERY'].includes(event))setTimeout(()=>acceptAuthSession(session,event),0)});return cloudClient})();try{return await cloudLoading}catch(e){cloudLoading=null;throw e}}
async function cloudAttach(user,force=false){if(!force&&user?.id===cloudUser?.id)return;if(typeof socialReset==='function')socialReset();if(typeof resetAccountEditors==='function')resetAccountEditors();const epoch=++cloudEpoch;clearTimeout(cloudTimer);cloudReady=false;cloudUser=user;cloudDirty=false;cloudRevision=0;if(!user){try{state={...initial(),...JSON.parse(localStorage.getItem(KEY)||'null')}}catch(e){state=initial()}cloudMessage('Sign in to save across devices.');render();return}state=initial();let cache=null;try{cache=JSON.parse(localStorage.getItem(cloudCacheKey())||'null');if(cache&&cloudValid(cache.data)){state=cache.data;cloudRevision=cache.revision;cloudDirty=cache.dirty}}catch(e){}render();cloudMessage('Opening your private journal…');try{const {data,error}=await cloudClient.from('dogleg_journals').select('data,revision').eq('user_id',user.id).maybeSingle();if(epoch!==cloudEpoch)return;if(error)throw error;if(data&&!cloudValid(data.data))throw Error('Cloud journal could not be validated. Export your local backup and contact support.');if(cloudDirty){cloudReady=true;if((data?.revision||0)!==cloudRevision){cloudReady=false;cloudMessage('Another device has newer changes. Export this device’s backup, then load the latest cloud journal and import the backup to merge missing records.')}else{cloudMessage('Device changes are waiting to save.');cloudSave()}}else{state=data?data.data:initial();if(!data)state.profile.name=String(user.user_metadata?.display_name||user.email?.split('@')[0]||'Golfer').slice(0,50);cloudRevision=data?.revision||0;cloudReady=true;cloudDirty=false;cloudCache();cloudMessage(data?'Saved to Supabase.':'Private journal ready. Add a round or import your original browser journal.')}render()}catch(e){if(epoch!==cloudEpoch)return;cloudMessage('Could not open cloud journal. Your cached data is available; reconnect before saving.');render()}}
async function cloudSave(){if(!cloudUser||!cloudReady){cloudMessage(cloudUser?'Reconnect or load the latest cloud journal before saving.':'Sign in to save your journal to Supabase.');return}if(cloudBusy)return;if(!cloudDirty&&cloudRevision>0){cloudMessage('Saved to Supabase.');return}if(!cloudValid(state)){cloudMessage('Journal validation failed. Export a backup before continuing.');return}const epoch=cloudEpoch,user=cloudUser,snapshot=JSON.stringify(state),revision=cloudRevision;cloudBusy=true;cloudMessage('Saving to Supabase…');try{const row={user_id:user.id,data:JSON.parse(snapshot),revision:revision+1,updated_at:new Date().toISOString()};const query=revision===0?cloudClient.from('dogleg_journals').insert(row):cloudClient.from('dogleg_journals').update(row).eq('user_id',user.id).eq('revision',revision);const {data,error}=await query.select('revision').maybeSingle();if(epoch!==cloudEpoch)return;if(error||!data){if(!data&&!error||error?.code==='23505'){cloudReady=false;throw Error('Another device has newer changes. Export a backup, load the latest cloud journal, then import your backup to merge missing records.')}throw error}cloudRevision=data.revision;cloudDirty=JSON.stringify(state)!==snapshot;cloudCache();cloudMessage(cloudDirty?'More changes waiting to save.':'Saved to Supabase.')}catch(e){if(epoch===cloudEpoch)cloudMessage(e.message||'Cloud save failed. Your changes remain on this device.')}finally{cloudBusy=false;if(epoch===cloudEpoch&&cloudDirty&&cloudReady&&cloudRevision>revision)cloudTimer=setTimeout(cloudSave,400)}}
function cloudReloadPrompt(){if(!cloudUser)return;if(cloudBusy)return toast('Wait for the current save to finish.');openModal('Load your cloud journal?',`<p>Any unsaved changes on this device will be replaced. Export a V7 backup first to keep them, then import it afterwards to merge missing rounds and memories.</p><div class="form-actions"><button class="secondary" onclick="exportData()">Export backup</button><button onclick="cloudReload()">Load cloud journal</button></div>`)}
async function cloudReload(){if(cloudBusy)return;const user=cloudUser;if(!user)return;try{const {data,error}=await cloudClient.from('dogleg_journals').select('data,revision').eq('user_id',user.id).maybeSingle();if(user.id!==cloudUser?.id)return;if(error)throw error;if(data&&!cloudValid(data.data))throw Error('Cloud journal validation failed.');localStorage.setItem(cloudCacheKey()+':before-reload',JSON.stringify(state));state=data?.data||initial();cloudRevision=data?.revision||0;cloudReady=true;cloudDirty=false;cloudCache();modal.close();cloudMessage('Latest cloud journal loaded.');render()}catch(e){cloudMessage(e.message||'Could not load cloud journal. Your current data is unchanged.')}}
function cloudImportGuest(){if(!cloudUser||!cloudReady)return toast('Open your cloud journal first.');try{const guest=JSON.parse(localStorage.getItem(KEY)||'null');if(!guest||!cloudValid(guest))return toast('No original browser journal found. Use Import V7 backup instead.');state=cloudMerge(state,guest);persist();render();toast('Original browser rounds and memories imported. Existing cloud records kept. Update your name in Player profile if needed.')}catch(e){toast('Could not import the original browser journal. Use a V7 backup instead.')}}
async function cloudSignOut(){if(cloudBusy)return toast('Wait for the current save to finish.');try{const {error}=await cloudClient.auth.signOut({scope:'local'});if(error)throw error;try{localStorage.removeItem(GUEST_STORAGE)}catch(e){}authMode='signin';authNotice='';await acceptAuthSession(null,'SIGNED_OUT')}catch(e){cloudMessage('Could not log out. Try again.')}}
if(typeof views!=='undefined'){
 const localPersist=persist,localRender=render,profileView=views.Profile;
 persist=function(){if(!cloudUser)return localPersist();cloudDirty=true;const saved=cloudCache();cloudMessage('Saved on this device · Cloud save pending.');clearTimeout(cloudTimer);if(cloudReady)cloudTimer=setTimeout(cloudSave,600);return saved};
 views.Profile=()=>profileView()+cloudPanel();
 render=function(){document.body.classList.toggle('auth-mode',authScreen!=='app');if(authScreen!=='app'){main.innerHTML=authView();return}localRender();const account=document.querySelector('header .avatar');account.classList.toggle('login-entry',!cloudUser);account.onclick=openAccount;if(!cloudUser){account.textContent='Log in';account.setAttribute('aria-label','Log in to your account')}else{account.setAttribute('aria-label','Open your profile');cloudMessage(cloudStatus)}};
 window.addEventListener('online',()=>{if(cloudUser&&cloudReady)cloudSave();else if(cloudUser)reconnectCloud()});
 setTimeout(cloudBoot,0);
}
